size_t GetQuantumExtent(const Image *image, const QuantumInfo *quantum_info, const QuantumType quantum_type) {
  if (quantum_info == (QuantumInfo *) NULL) {
    return 0;
  }

  if (memcmp(quantum_info->signature, MagickSignature, sizeof(quantum_info->signature)) != 0) {
    return 0;
  }

  size_t packet_size = 0;

  switch (quantum_type) {
    case RedQuantum:
    case GreenQuantum:
    case BlueQuantum:
    case IndexQuantum:
      packet_size = 1;
      break;
    case OpacityQuantum:
      packet_size = 1;
      break;
    case RGBQuantum:
      packet_size = 3;
      break;
    case RGBAQuantum:
      packet_size = 4;
      break;
    default:
      packet_size = 0;
      break;
  }

  return packet_size;
}
